#!/usr/bin/env python3
"""Outcomes -> drop-off funnel (with Withdrew-onboarding bucket). Run from ~/Command-Centre."""
import base64
f="recruitment.html"
s=open(f,encoding="utf-8").read()
o=base64.b64decode("").decode()
w=base64.b64decode("").decode()
if "Where coaches drop off" in s: print("already applied")
elif o in s:
    open(f,"w",encoding="utf-8").write(s.replace(o,w,1)); print("patched OK -> drop-off funnel live")
else: print("COULD NOT FIND Outcomes block - tell Claude")
